#' \code{value}, the lower-bound loss of the returned clustering.
#' @keywords internal
#' @export
minVIGreedyRefine <- function(psm, init, max_passes = 50L) {
    .Call('_batchmix_minVIGreedyRefine', PACKAGE = 'batchmix', psm, init, max_passes)
}

